  // ─── 演示 1：坐标系实验台 ────────────────────────────────────────────────
  function buildFramesDemo(host) {
    var root = card(host, {
      title: '坐标系实验台：头在动，未来的手位置换不换到当前相机坐标系，差多少',
      sub: '数据是官方样例数据里一段人的示范（碗任务，300 帧、30 帧每秒），不是论文的实验。拖动第 $t$ 帧，看之后 0.9 秒的 10 个手的位置：黄点直接用各自那一帧的坐标，紫点是换到第 $t$ 帧的相机坐标系以后的。'
    });
    var state = { t: EGO.human.shift_at, view: 'xy' };
    var row = controlsRow(root);
    slider(row, { label: '第 $t$ 帧', min: 0, max: HN - 28, step: 1, value: state.t, format: function (v) { return v + '（' + f2(v / 30) + ' 秒）'; }, onInput: function (v) { state.t = v; render(); } });
    buttonGroup(root, { label: '从哪个方向看', value: 'xy', items: [{ label: '画面的朝向（x–y）', value: 'xy' }, { label: '从上往下（x–z）', value: 'xz' }], onPick: function (v) { state.view = v; render(); } });
    var st1 = stage(root, 280), st2 = stage(root, 170);
    var stats = statsRow(root), sEnd = stats.add('0.9 秒后那个点相差'), sMove = stats.add('手自己走了'), sMean = stats.add('这一段的平均'), sAll = stats.add('整份样例的平均');
    var verdict = verdictBox(root);
    note(root, [
      '上图：白圈是第 $t$ 帧的手。紫点 ${}^Ha^p_i=(T^W_{F_t})^{-1}T^W_{F_i}\\,p^{F_i}_i$ 是数据集里存的动作（`actions_xyz`，10 个点、每 3 帧一个）；黄点是第 $t+3i$ 帧的 `obs/ee_pose`，也就是没有换坐标系的 $p^{F_i}_i$。两组点的第一个重合；头动得越多，后面的点分得越开。',
      '下图：整段 300 帧里，0.9 秒后那个点两种算法相差多少（厘米）。竖线是当前的 $t$。',
      '数据来自 HF gatech/EgoMimic 的 `bowlplace_human.hdf5` 第 0 组，位置量化到毫米。整份样例（13,335 个样本）的平均是 4.6 厘米、最大 64.6 厘米。'
    ]);
    function render() {
      var g = begin(st1), P = g.P, t = state.t, a = state.view === 'xy' ? 1 : 2;
      var lo = a === 1 ? -0.10 : 0.25, hi = a === 1 ? 0.50 : 0.70;
      var p = K.plot(g, { l: 46, r: 16, t: 16, b: 34 }, [-0.25, 0.55], a === 1 ? [hi, lo] : [lo, hi]);
      K.axes(g, p, { xTicks: [-0.2, 0, 0.2, 0.4], yTicks: K.niceTicks(lo, hi, 4), xFmt: function (v) { return f1(v); }, yFmt: function (v) { return f1(v); }, xLabel: 'x（米）', yLabel: a === 1 ? 'y（米）' : 'z（米）' });
      var raw = [], act = [];
      for (var i = 0; i < 10; i++) { raw.push(hRaw(t, i)); act.push(hAct(t, i)); }
      K.line(g.ctx, raw.map(function (q) { return [p.sx(q[0]), p.sy(q[a])]; }), P.warn, 1.2, [4, 3]);
      K.line(g.ctx, act.map(function (q) { return [p.sx(q[0]), p.sy(q[a])]; }), P.purple, 1.2);
      raw.forEach(function (q) { K.dot(g.ctx, p.sx(q[0]), p.sy(q[a]), 4, P.warn); });
      act.forEach(function (q) { K.dot(g.ctx, p.sx(q[0]), p.sy(q[a]), 4, P.purple); });
      var e = hEE(t);
      g.ctx.strokeStyle = P.text; g.ctx.lineWidth = 2; g.ctx.beginPath(); g.ctx.arc(p.sx(e[0]), p.sy(e[a]), 7, 0, 6.2832); g.ctx.stroke();
      text(g.ctx, '黄：不换坐标系　紫：换到第 t 帧', p.x1, p.y1 - 4, P.muted, 'right', '12px sans-serif');
      var d = dist3(raw[9], act[9]), mv = dist3(act[9], act[0]);
      var g2 = begin(st2), P2 = g2.P, series = [], sum = 0;
      for (var k = 0; k <= HN - 28; k++) { var v = 100 * dist3(hRaw(k, 9), hAct(k, 9)); series.push(v); sum += v; }
      var mx = Math.max.apply(null, series);
      var p2 = K.plot(g2, { l: 46, r: 16, t: 14, b: 32 }, [0, HN - 28], [0, mx * 1.08]);
      K.axes(g2, p2, { xTicks: [0, 90, 180, 270], yTicks: K.niceTicks(0, mx, 4), xLabel: '第几帧', yLabel: '厘米' });
      K.line(g2.ctx, series.map(function (v, i) { return [p2.sx(i), p2.sy(v)]; }), P2.warn, 1.8);
      K.line(g2.ctx, [[p2.sx(t), p2.y0], [p2.sx(t), p2.y1]], P2.text, 1, [3, 3]);
      sEnd.set(f1(100 * d) + ' 厘米'); sMove.set(f1(100 * mv) + ' 厘米'); sMean.set(f1(sum / series.length) + ' 厘米'); sAll.set(f1(EGO.head.mean * 100) + ' 厘米');
      verdict.set(d > 0.10 ? '这 0.9 秒里头动得多：不换坐标系的话，动作里有 ' + f1(100 * d) + ' 厘米其实是头的移动。' :
        d > 0.03 ? '头有一点移动：两组点分开了几厘米。' : '这 0.9 秒里头几乎没动：换不换差不多。', d > 0.10 ? 'warn' : 'good');
    }
    registerRenderer(render);
    render();
  }

  // ─── 演示 2：归一化实验台 ────────────────────────────────────────────────
  function buildNormDemo(host) {
    var root = card(host, {
      title: '归一化实验台：手和夹爪的位置分布，归一化前后',
      sub: '数据是官方样例数据（碗任务）里全部的 `obs/ee_pose`：手 14,685 个样本、夹爪 12,000 个，不是论文的实验。选一个方向，再在「归一化前 / 后」之间切换。'
    });
    var state = { dim: 1, norm: 0 };
    buttonGroup(root, { label: '方向', value: 1, items: [{ label: 'x', value: 0 }, { label: 'y', value: 1 }, { label: 'z', value: 2 }], onPick: function (v) { state.dim = v; render(); } });
    buttonGroup(root, { label: '横轴', value: 0, items: [{ label: '归一化前（米）', value: 0 }, { label: '各自归一化以后', value: 1 }], onPick: function (v) { state.norm = v; render(); } });
    var st = stage(root, 260);
    var stats = statsRow(root), sH = stats.add('手：均值 ± 标准差'), sR = stats.add('夹爪：均值 ± 标准差'), sGap = stats.add('两个均值相差'), sOv = stats.add('两条曲线重叠的面积');
    var tb = table(root);
    var verdict = verdictBox(root);
    note(root, [
      '曲线是直方图（每格的样本占比）：粉色是手，蓝色是夹爪。归一化是 $\\mathrm{norm}(p)=(p-\\mu)/\\sigma$，手和夹爪各用各的 $\\mu$、$\\sigma$。',
      '论文图 3 (a) 画的是 $y$ 这一维，图注把它叫左右方向；把这些位置按官方代码的相机内参投到画面上，$y$ 对应的是画面的上下方向。',
      '「重叠的面积」是两条直方图逐格取较小值再相加，1 表示完全重合。只代表这份样例数据。'
    ]);
    function render() {
      var g = begin(st), P = g.P, d = state.dim, key = state.norm ? 'norm' : 'raw', H = EGO.hist[key];
      var a = H.hand[d], b = H.robot[d], mx = Math.max(Math.max.apply(null, a), Math.max.apply(null, b));
      var p = K.plot(g, { l: 46, r: 16, t: 16, b: 34 }, [H.lo, H.hi], [0, mx * 1.1]);
      K.axes(g, p, { xTicks: state.norm ? [-4, -2, 0, 2, 4] : [-0.2, 0, 0.2, 0.4, 0.6], yTicks: K.niceTicks(0, mx, 3), xFmt: function (v) { return state.norm ? String(v) : f1(v); }, yFmt: function (v) { return f2(v); },
        xLabel: ['x', 'y', 'z'][d] + (state.norm ? '（归一化以后）' : '（米）'), yLabel: '占比' });
      function pts(arr) { return arr.map(function (v, i) { return [p.sx(H.lo + (i + 0.5) * (H.hi - H.lo) / H.n), p.sy(v)]; }); }
      K.line(g.ctx, pts(b), P.accent, 2.2); K.line(g.ctx, pts(a), P.purple, 2.2);
      text(g.ctx, '粉：手　蓝：夹爪', p.x1, p.y1 - 4, P.muted, 'right', '12px sans-serif');
      var S = EGO.stats, ov = 0;
      for (var i = 0; i < H.n; i++) ov += Math.min(a[i], b[i]);
      sH.set(f3(S.hand.mean[d]) + ' ± ' + f3(S.hand.std[d]) + ' 米'); sR.set(f3(S.robot.mean[d]) + ' ± ' + f3(S.robot.std[d]) + ' 米');
      sGap.set(state.norm ? '0（各自减了均值）' : f3(Math.abs(S.hand.mean[d] - S.robot.mean[d])) + ' 米'); sOv.set(f2(ov));
      tb.clear();
      tb.row(['方向', '手的均值', '手的标准差', '夹爪的均值', '夹爪的标准差'], true);
      ['x', 'y', 'z'].forEach(function (n, k) { tb.row([n, f3(S.hand.mean[k]), f3(S.hand.std[k]), f3(S.robot.mean[k]), f3(S.robot.std[k])]); });
      verdict.set(state.norm ? '各自归一化以后，两条曲线的中心都在 0、宽度都是 1；形状的差别还在。' :
        d === 1 ? '$y$ 这一维：手的均值 0.236 米，夹爪 0.003 米，两座峰几乎不重叠。' : '这一维两种数据本来就比较接近。', state.norm || d !== 1 ? 'good' : 'warn');
    }
    registerRenderer(render);
    render();
  }

